---

## Why Use Both In-Memory and localStorage?

- **In-memory cache** (a JavaScript `Map`) is very fast but clears on page reload.
- **localStorage** persists data across sessions but is slower and has size limits.
- Using both lets you serve cached data instantly during a session and reload cached data on page load without hitting the API unnecessarily.

---

## Key Features of This Caching System

- Cache API responses keyed by city name (or query string).
- Store a timestamp with each cached entry to enforce expiration (TTL).
- Limit localStorage cache size to last 3 searched cities to avoid storage bloat.
- Use async/await with proper error handling.
- Return cached data if valid, otherwise fetch fresh data and update cache.
- Simple API to get weather data with caching transparently handled.

---

## Complete Example Implementation

```javascript
const CACHE_KEY = 'weather_cache';
const CACHE_TTL = 60 * 60 * 1000; // 1 hour TTL
const MAX_LOCALSTORAGE_ENTRIES = 3;

// In-memory cache for fast access during session
const memoryCache = new Map();

// Load cache from localStorage on app start
function loadCacheFromStorage() {
  try {
    const raw = localStorage.getItem(CACHE_KEY);
    if (!raw) return new Map();
    const parsed = JSON.parse(raw);
    // Convert object back to Map with city keys and { data, timestamp }
    return new Map(Object.entries(parsed));
  } catch (e) {
    console.warn('Failed to load cache from localStorage', e);
    return new Map();
  }
}

// Save cache Map to localStorage (only last 3 entries)
function saveCacheToStorage(cacheMap) {
  try {
    // Keep only last MAX_LOCALSTORAGE_ENTRIES entries (by insertion order)
    const entries = Array.from(cacheMap.entries());
    const limitedEntries = entries.slice(-MAX_LOCALSTORAGE_ENTRIES);
    const objToStore = Object.fromEntries(limitedEntries);
    localStorage.setItem(CACHE_KEY, JSON.stringify(objToStore));
  } catch (e) {
    console.warn('Failed to save cache to localStorage', e);
  }
}

// Initialize memory cache from localStorage on load
const localStorageCache = loadCacheFromStorage();
for (const [key, value] of localStorageCache.entries()) {
  memoryCache.set(key, value);
}

// Helper to check if cached entry is still valid
function isCacheValid(timestamp) {
  return (Date.now() - timestamp) < CACHE_TTL;
}

// Fetch weather data from API with caching
async function getWeatherData(city) {
  const cityKey = city.toLowerCase();

  // Check in-memory cache first
  if (memoryCache.has(cityKey)) {
    const cached = memoryCache.get(cityKey);
    if (isCacheValid(cached.timestamp)) {
      console.log(`Serving ${city} from in-memory cache`);
      return cached.data;
    }
    // Cache expired, remove it
    memoryCache.delete(cityKey);
  }

  // If not in memory or expired, check localStorage cache
  if (localStorageCache.has(cityKey)) {
    const cached = localStorageCache.get(cityKey);
    if (isCacheValid(cached.timestamp)) {
      console.log(`Serving ${city} from localStorage cache`);
      // Update in-memory cache for faster access next time
      memoryCache.set(cityKey, cached);
      return cached.data;
    }
    // Expired in localStorage, remove it
    localStorageCache.delete(cityKey);
  }

  // Fetch fresh data from API
  try {
    const apiKey = 'YOUR_API_KEY'; // Replace with your actual key
    const url = `https://api.openweathermap.org/data/2.5/weather?q=${encodeURIComponent(city)}&units=metric&appid=${apiKey}`;
    const response = await fetch(url);

    if (!response.ok) {
      // Handle HTTP errors with status codes
      if (response.status === 404) throw new Error('City not found (404)');
      if (response.status === 401) throw new Error('Unauthorized (401) - Invalid API key');
      if (response.status === 429) throw new Error('Too many requests (429) - Rate limit exceeded');
      throw new Error(`HTTP error ${response.status}`);
    }

    const data = await response.json();

    // Cache the fresh data with timestamp
    const cacheEntry = { data, timestamp: Date.now() };
    memoryCache.set(cityKey, cacheEntry);
    localStorageCache.set(cityKey, cacheEntry);
    saveCacheToStorage(localStorageCache);

    console.log(`Fetched fresh data for ${city} from API`);
    return data;
  } catch (error) {
    console.error('Error fetching weather data:', error.message);
    throw error; // Let caller handle error display
  }
}
```

